#import "TFAISubtasks.h"
static NSError *TaskError(NSString *text){return [NSError errorWithDomain:@"Dylix.Subtask" code:1 userInfo:@{NSLocalizedDescriptionKey:text}];}
static NSString *Bound(NSString *text,NSUInteger limit){return text.length>limit?[text substringToIndex:limit]:text?:@"";}
@interface TFAISubtasks ()
@property NSString *path;
@property NSMutableArray *records;
@property NSMutableDictionary *cancellations,*executors;
@end
@implementation TFAISubtasks
+ (instancetype)shared{static id shared;static dispatch_once_t once;dispatch_once(&once,^{NSString *path=[NSSearchPathForDirectoriesInDomains(NSApplicationSupportDirectory,NSUserDomainMask,YES).firstObject stringByAppendingPathComponent:@"Dylix/Agent/subtasks.json"];shared=[[self alloc]initWithPath:path];});return shared;}
- (instancetype)initWithPath:(NSString *)path{if((self=[super init])){_path=path;_records=[NSMutableArray new];_cancellations=[NSMutableDictionary new];_executors=[NSMutableDictionary new];id data=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:path]?:NSData.data options:NSJSONReadingMutableContainers error:nil];if([data isKindOfClass:NSArray.class])for(id item in data){if(_records.count>=100)break;if(![item isKindOfClass:NSDictionary.class]||![[NSUUID alloc]initWithUUIDString:item[@"id"]]||![item[@"parent"] isKindOfClass:NSString.class]||![item[@"root"] isKindOfClass:NSString.class])continue;NSMutableDictionary *row=[item mutableCopy];if([row[@"state"] isEqual:@"running"]){row[@"state"]=@"interrupted";row[@"stage"]=@"进程已重启，须明确继续";}[_records addObject:row];}}return self;}
- (void)persist{if(![self.path isEqual:self.path.stringByResolvingSymlinksInPath])return;[NSFileManager.defaultManager createDirectoryAtPath:self.path.stringByDeletingLastPathComponent withIntermediateDirectories:YES attributes:@{NSFilePosixPermissions:@0700} error:nil];NSData *data=[NSJSONSerialization dataWithJSONObject:self.records options:0 error:nil];if([data writeToFile:self.path options:NSDataWritingAtomic error:nil])[NSFileManager.defaultManager setAttributes:@{NSFilePosixPermissions:@0600} ofItemAtPath:self.path error:nil];}
- (NSArray *)tasks:(NSString *)parent{NSMutableArray *out=[NSMutableArray new];for(NSDictionary *row in self.records)if([row[@"parent"] isEqual:parent]){NSMutableDictionary *public=[row mutableCopy];[public removeObjectForKey:@"prompt"];[public removeObjectForKey:@"root"];[out addObject:public];}return out;}
- (BOOL)capacity:(NSString *)parent{NSUInteger active=0;for(NSDictionary *row in self.records)if([row[@"parent"] isEqual:parent]&&[row[@"state"] isEqual:@"running"])active++;return active<3;}
- (void)run:(NSMutableDictionary *)row executor:(TFAISubtaskExecutor)executor{NSString *identifier=row[@"id"],*attempt=NSUUID.UUID.UUIDString;self.executors[identifier]=[executor copy];row[@"attempt"]=attempt;row[@"state"]=@"running";row[@"stage"]=@"启动专用任务";row[@"startedAt"]=@(NSDate.date.timeIntervalSince1970);[row removeObjectForKey:@"finishedAt"];[self persist];__weak typeof(self) weak=self;dispatch_block_t cancel=executor(row.copy,^(NSString *stage,NSString *partial){if(![row[@"attempt"] isEqual:attempt]||![row[@"state"] isEqual:@"running"])return;row[@"stage"]=Bound(stage,160);row[@"partial"]=Bound(partial,8192);[weak persist];},^(NSDictionary *result,NSError *error){if(![row[@"attempt"] isEqual:attempt]||![row[@"state"] isEqual:@"running"])return;row[@"state"]=error?@"failed":@"completed";row[@"stage"]=error?Bound(error.localizedDescription,160):@"任务已完成，结果供父会话核对";row[@"finishedAt"]=@(NSDate.date.timeIntervalSince1970);row[@"result"]=result?:@{};NSData *encoded=[NSJSONSerialization dataWithJSONObject:row[@"result"] options:0 error:nil];if(encoded.length>32*1024)row[@"result"]=@{@"summary":Bound(result[@"summary"],8192),@"truncated":@YES};[weak.cancellations removeObjectForKey:identifier];[weak persist];});if(cancel&&[row[@"state"] isEqual:@"running"])self.cancellations[identifier]=[cancel copy];}
- (NSDictionary *)start:(NSString *)kind prompt:(NSString *)prompt parent:(NSString *)parent root:(NSString *)root executor:(TFAISubtaskExecutor)executor error:(NSError **)error{
 if(![@[@"analysis",@"build"] containsObject:kind]||!prompt.length||prompt.length>8000||!parent.length||!root.length||!executor||![self capacity:parent]){if(error)*error=TaskError(@"子任务需有效项目、analysis/build、1–8000字目标；每父会话最多3个运行中任务。");return nil;}
 while(self.records.count>=100){NSUInteger at=[self.records indexOfObjectPassingTest:^BOOL(NSDictionary *r,NSUInteger i,BOOL *stop){return ![r[@"state"] isEqual:@"running"];}];if(at==NSNotFound){if(error)*error=TaskError(@"任务记录已满，请等待任务完成。");return nil;}[self.executors removeObjectForKey:self.records[at][@"id"]];[self.records removeObjectAtIndex:at];}
 NSMutableDictionary *row=[@{@"id":NSUUID.UUID.UUIDString,@"parent":parent,@"root":root,@"kind":kind,@"prompt":prompt,@"depth":@1,@"createdAt":@(NSDate.date.timeIntervalSince1970)} mutableCopy];[self.records addObject:row];[self run:row executor:executor];return [self tasks:parent].lastObject;
}
- (NSDictionary *)resume:(NSString *)identifier parent:(NSString *)parent executor:(TFAISubtaskExecutor)executor error:(NSError **)error{for(NSMutableDictionary *row in self.records)if([row[@"id"] isEqual:identifier]&&[row[@"parent"] isEqual:parent]){if(!executor)executor=self.executors[identifier];if([row[@"state"] isEqual:@"running"]||![self capacity:parent]||!executor){if(error)*error=TaskError(@"任务正在运行或并发已满。");return nil;}[self run:row executor:executor];for(NSDictionary *item in [self tasks:parent])if([item[@"id"] isEqual:identifier])return item;}if(error)*error=TaskError(@"子任务不属于当前会话。");return nil;}
- (BOOL)canResume:(NSString *)identifier parent:(NSString *)parent{for(NSDictionary *row in self.records)if([row[@"id"] isEqual:identifier]&&[row[@"parent"] isEqual:parent])return ![row[@"state"] isEqual:@"running"]&&self.executors[identifier]!=nil&&[self capacity:parent];return NO;}
- (BOOL)cancel:(NSString *)identifier parent:(NSString *)parent{for(NSMutableDictionary *row in self.records)if([row[@"id"] isEqual:identifier]&&[row[@"parent"] isEqual:parent]){if(![row[@"state"] isEqual:@"running"])return YES;row[@"state"]=@"cancelled";row[@"stage"]=@"已取消，部分结果保留；已开始的构建按步骤边界停止";row[@"finishedAt"]=@(NSDate.date.timeIntervalSince1970);dispatch_block_t cancel=self.cancellations[identifier];[self.cancellations removeObjectForKey:identifier];if(cancel)cancel();[self persist];return YES;}return NO;}
- (void)cancelParent:(NSString *)parent{for(NSDictionary *row in [self tasks:parent])[self cancel:row[@"id"] parent:parent];}
@end
